import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, {alpha} students are analyzing a weighted divisibility network. For each integer k with {lower} ≤ k ≤ {alpha}, choose real numbers x_1, x_2, ..., x_k ∈ [0,1] to maximize\n\nF_k = x_1^{ {p} } + x_2^{ {p} } + ⋯ + x_k^{ {p} } − ∑_{1 ≤ i < j ≤ k, i | j, j/i ≤ {m}} x_i^{ {q} } x_j^{ {q} }.\n\nLet d(k) denote the maximum value of F_k. Compute the sum ∑_{k={lower}}^{ {alpha} } d(k).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose alpha moderately large to make the range nontrivial
alpha = rng.randint(800, 4000)
# Choose lower at least 3 and well below alpha to enforce a long sum
# Ensure range length at least 100 for difficulty
max_lower = alpha - 150
if max_lower < 3:
    # rare, but guard
    max_lower = 3
lower = rng.randint(3, max_lower)
# Choose m >= 2 (ratio cap), not too large to avoid triviality
m = rng.randint(2, 9)
# Choose exponents with p > q >= 1
q = rng.randint(1, 5)
p = rng.randint(q + 1, q + rng.randint(2, 4))
# Clip p to reasonable bound
p = min(p, 9)
# Ensure at least 100 terms in the sum
if alpha - lower + 1 < 100:
    # Retry by bumping alpha and/or lowering lower
    # Guarantee using rng to change state
    bump = rng.randint(100, 300)
    alpha += bump
    lower = max(3, lower - rng.randint(0, 50))
return {'alpha': alpha, 'lower': lower, 'm': m, 'p': p, 'q': q}

    def verifier(assign):
# Validate presence of required keys
for key in ['alpha', 'lower', 'm', 'p', 'q']:
    if key not in assign:
        # Missing parameters
        return False, None  # missing keys
alpha = assign['alpha']
lower = assign['lower']
m = assign['m']
p = assign['p']
q = assign['q']
# Basic type and domain checks
if not (isinstance(alpha, int) and isinstance(lower, int) and isinstance(m, int) and isinstance(p, int) and isinstance(q, int)):
    return False, None  # wrong types
if alpha < lower or lower < 3:
    return False, None  # invalid range
if m < 2:
    return False, None  # trivial/undefined ratio cap
if not (p > q >= 1):
    return False, None  # exponent condition needed for reduction
# Enforce difficulty: range length should be reasonably large
if alpha - lower + 1 < 50:
    return False, None  # too short; risks triviality
# Compute the answer using the proven formula d(k) = k - floor(k/m)
# Sum_{k=lower}^alpha [k - floor(k/m)]
total = 0
# A simple loop is fine for alpha up to a few thousand
for k in range(lower, alpha + 1):
    total += k - (k // m)
return True, total


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

